/**
 * Story and test support for ResourceDetail, ResourceImport and
 * ChangeHistory: the backend's own OpenAPI snapshot (generated by the Python
 * suite as packages/karni/tests/api/fixtures/schema.testapp.json, copied to
 * tests/fixtures/), a testapp Event, and msw handlers that answer every
 * state those components show — slow, offline, 403, 404, 500, partial
 * permission.
 *
 * Test/story support only — never imported by shipped component code.
 */
import { delay, http, HttpResponse, type RequestHandler } from "msw";
import snapshot from "../../../tests/fixtures/schema.testapp.json";
import type { ChangeHistoryPage } from "../../hooks/useChangeHistory";
import type { ImportDescription, ImportJob } from "../../hooks/useResourceImport";

/** The OpenAPI document `/api/schema/` serves for the testapp (a superuser's view). */
export const testappOpenApi = snapshot as unknown as Record<string, unknown>;

interface SchemaObject {
  properties?: Record<string, unknown>;
  required?: string[];
}

const EVENT_COMPONENTS = ["TestappEvent", "TestappEventRequest", "PatchedTestappEventRequest"];

/**
 * The per-role document of a role `Karni.field_roles` hides `fields` of the
 * Event from: the fields are absent from it, as they are from the payload.
 */
export function openApiHidingEventFields(fields: readonly string[]): Record<string, unknown> {
  const doc = JSON.parse(JSON.stringify(testappOpenApi)) as {
    components: { schemas: Record<string, SchemaObject | undefined> };
  };
  for (const name of EVENT_COMPONENTS) {
    const component = doc.components.schemas[name];
    if (component === undefined) continue;
    for (const field of fields) delete component.properties?.[field];
    if (component.required !== undefined) {
      component.required = component.required.filter((field) => !fields.includes(field));
    }
  }
  return doc as unknown as Record<string, unknown>;
}

