/** The same Event as a role that may not read `fields` receives it: the keys are absent, not null. */
export function eventHiding(fields: readonly string[]): Record<string, unknown> {
  return Object.fromEntries(Object.entries(demoEvent).filter(([key]) => !fields.includes(key)));
}

/**
 * How one endpoint answers: "ok"; "pending" (never answers: the loading
 * state); "network" (the request fails, as offline); a status with an
 * optional DRF body; or a delay before answering "ok".
 */
export type Outcome =
  "ok" | "pending" | "network" | { status: number; body?: unknown } | { delayMs: number };

async function respond(outcome: Outcome, ok: () => Response): Promise<Response> {
  if (outcome === "ok") return ok();
  if (outcome === "pending") {
    await delay("infinite");
    return ok();
  }
  if (outcome === "network") return HttpResponse.error();
  if ("delayMs" in outcome) {
    await delay(outcome.delayMs);
    return ok();
  }
  return HttpResponse.json(outcome.body ?? {}, { status: outcome.status });
}

/** The 404 Karni answers for a row outside the read scope: the scope is named, existence is not. */
export const SCOPED_NOT_FOUND = {
  status: 404,
  body: {
    detail:
      "No Event matches the given query. Rows are limited by EventViewSet.access read=Granted().",
  },
} as const;

export interface DetailBackend {
  schema?: Outcome;
  /** The document `/api/schema/` serves (default: the testapp snapshot). */
  openApi?: Record<string, unknown>;
  event?: Outcome;
  /** The payload `GET /api/events/<id>/` answers (default: demoEvent). */
  record?: Record<string, unknown>;
  remove?: Outcome;
  history?: Outcome;
  historyPage?: ChangeHistoryPage;
}

/** msw handlers for the schema, one Event, its delete and its history. */
export function detailBackend(options: DetailBackend = {}): RequestHandler[] {
  const openApi = options.openApi ?? testappOpenApi;
  const record = options.record ?? demoEvent;
  return [
    http.get("*/api/schema/", () =>
      respond(options.schema ?? "ok", () => HttpResponse.json(openApi)),
    ),
    http.get("*/api/events/:id/history/", () =>
      respond(options.history ?? "ok", () => HttpResponse.json(options.historyPage ?? demoHistory)),
    ),
    http.get("*/api/events/:id/", () =>
      respond(options.event ?? "ok", () => HttpResponse.json(record)),
    ),
    http.delete("*/api/events/:id/", () =>
      respond(options.remove ?? "ok", () => new HttpResponse(null, { status: 204 })),
    ),
  ];
}

