// import

function column(
  name: string,
  label: string,
  kind: ImportDescription["fields"][number]["kind"],
  extra: Partial<ImportDescription["fields"][number]> = {},
): ImportDescription["fields"][number] {
  return {
    name,
    label,
    kind,
    required: false,
    readable: true,
    writable: true,
    choices: [],
    target: null,
    lookup: null,
    help: "",
    key: false,
    ...extra,
  };
}

