/** A preview: most rows import, two are refused with the reason. */
export const previewedJob = demoJob({
  status: "previewed",
  rows_done: 120,
  result: { rows_total: 120, created: 96, updated: 18, unchanged: 4, errors: 2, skipped: 6 },
  problems: [
    { row: 14, field: "starts_at", message: "Enter a valid date/time." },
    { row: 87, field: "venue", message: "No venue with name 'Lakeside Hall'." },
  ],
});

export const doneJob = demoJob({
  ...previewedJob,
  status: "done",
  batch: 7,
});

export interface ImportBackend {
  describe?: Outcome;
  upload?: Outcome;
  /** The job uploads create (default: demoJob()). */
  uploaded?: ImportJob;
  /** Answers of `GET .../import/<job>/` after a preview or commit started, in turn: polling. */
  polls?: readonly ImportJob[];
  preview?: Outcome;
  previewed?: ImportJob;
  commit?: Outcome;
  committed?: ImportJob;
}

/**
 * msw handlers for `/api/events/import/…`: describe, upload, poll, preview,
 * commit. `GET .../import/<job>/` answers the job as the last step left it
 * (after `polls`, while those last), as the backend does.
 */
export function importBackend(options: ImportBackend = {}): RequestHandler[] {
  const uploaded = options.uploaded ?? demoJob();
  const previewed = options.previewed ?? previewedJob;
  const committed = options.committed ?? doneJob;
  let current = uploaded;
  let poll = 0;
  return [
    http.get("*/api/events/import/", () =>
      respond(options.describe ?? "ok", () => HttpResponse.json(demoImportDescription)),
    ),
    http.post("*/api/events/import/", () =>
      respond(options.upload ?? "ok", () => {
        current = uploaded;
        return HttpResponse.json(uploaded, { status: 201 });
      }),
    ),
    http.get("*/api/events/import/:job/", () => {
      const polls = options.polls ?? [];
      if (current !== uploaded && poll < polls.length) {
        current = polls[poll] ?? current;
        poll += 1;
      }
      return HttpResponse.json(current);
    }),
    http.post("*/api/events/import/:job/preview/", () =>
      respond(options.preview ?? "ok", () => {
        current = previewed;
        return HttpResponse.json(previewed);
      }),
    ),
    http.post("*/api/events/import/:job/commit/", () =>
      respond(options.commit ?? "ok", () => {
        current = committed;
        return HttpResponse.json(committed);
      }),
    ),
  ];
}
